"""Read-only financial queries and exact-period calculations."""
from decimal import Decimal

from src.database import _configure
import psycopg
from psycopg.rows import dict_row

METRIC_LABELS = {"revenue": "Revenue", "net_income": "Net income", "operating_income": "Operating income",
                 "gross_profit": "Gross profit", "operating_cash_flow": "Operating cash flow",
                 "assets": "Assets", "liabilities": "Liabilities"}


def load_financials(dsn, schema="market_pulse"):
    """One read-only consistent snapshot; no queries are generated by users/AI."""
    with psycopg.connect(dsn, autocommit=True, connect_timeout=10, row_factory=dict_row,
                         application_name="market-pulse-dashboard") as conn:
        _configure(conn, schema)
        with conn.transaction():
            conn.execute("SET TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY")
            conn.execute("SET LOCAL statement_timeout = '15s'")
            companies = conn.execute("""SELECT c.cik,c.ticker,c.name,dc.dataset_id,dc.snapshot_id,dc.retrieved_at,
                dc.coverage,d.start_date,d.as_of FROM latest_company_datasets l
                JOIN companies c ON c.cik=l.cik
                JOIN dataset_companies dc ON (dc.cik,dc.dataset_id)=(l.cik,l.dataset_id)
                JOIN datasets d ON d.dataset_id=l.dataset_id ORDER BY c.name""").fetchall()
            observations = conn.execute("""SELECT o.*,f.value,f.tag,f.accession,f.filing_fy,f.filing_fp,
                fi.form,fi.filed,fi.source_url FROM latest_company_datasets l
                JOIN observations o ON (o.cik,o.dataset_id)=(l.cik,l.dataset_id)
                LEFT JOIN financial_facts f ON f.fact_id=o.selected_fact_id
                LEFT JOIN filings fi ON (fi.cik,fi.accession)=(f.cik,f.accession)
                ORDER BY o.cik,o.end_date,o.start_date,o.metric""").fetchall()
            annual_support = conn.execute("""SELECT DISTINCT f.cik,f.start_date,f.end_date
                FROM latest_company_datasets l JOIN dataset_facts df
                ON (df.cik,df.dataset_id)=(l.cik,l.dataset_id)
                JOIN financial_facts f ON f.fact_id=df.fact_id
                JOIN filings fi ON (fi.cik,fi.accession)=(f.cik,f.accession)
                WHERE f.metric='revenue' AND f.period_kind='year_duration'
                AND fi.form IN ('10-K','10-K/A') AND f.filing_fp='FY'""").fetchall()
    return {"companies": companies, "observations": observations, "annual_support": annual_support}


def ratio(numerator, denominator):
    if numerator is None or denominator is None or denominator <= 0:
        return None
    return numerator / denominator * Decimal(100)


def build_periods(data, cik, mode):
    """Revenue anchors define exact intervals; instant values match their ends."""
    if mode not in {"Annual", "Quarterly"}:
        raise ValueError("Unsupported reporting mode")
    rows = [r for r in data["observations"] if r["cik"] == cik]
    support = {(r["start_date"], r["end_date"]) for r in data["annual_support"] if r["cik"] == cik}
    anchors = {(r["start_date"], r["end_date"]) for r in rows if r["metric"] == "revenue" and
               ((mode == "Annual" and (r["start_date"], r["end_date"]) in support)
                or (mode == "Quarterly" and r["period_kind"] == "quarter_duration"))}
    result = []
    for start, end in sorted(anchors, key=lambda pair: (pair[1], pair[0])):
        period = dict(cik=cik, start_date=start, end_date=end, mode=mode, sources={}, issues=[])
        for metric in METRIC_LABELS:
            matching = [r for r in rows if r["metric"] == metric and r["end_date"] == end
                        and r["start_date"] == (None if metric in {"assets", "liabilities"} else start)]
            if len(matching) != 1 or matching[0]["status"] != "selected":
                period[metric] = None
                period["issues"].append(metric)
            else:
                period[metric] = matching[0]["value"]
                period["sources"][metric] = matching[0]
        period["net_margin"] = ratio(period["net_income"], period["revenue"])
        period["operating_margin"] = ratio(period["operating_income"], period["revenue"])
        period["gross_margin"] = ratio(period["gross_profit"], period["revenue"])
        period["liabilities_assets"] = ratio(period["liabilities"], period["assets"])
        # No forward interpolation, cumulative subtraction or fiscal-Q guessing.
        prior = [p for p in result if 351 <= (end-p["end_date"]).days <= 379
                 and abs((end-start).days-(p["end_date"]-p["start_date"]).days) <= 7]
        period["revenue_growth"] = None
        period["growth_source"] = None
        if len(prior) == 1 and prior[0]["revenue"] is not None and prior[0]["revenue"] > 0 and period["revenue"] is not None:
            period["revenue_growth"] = (period["revenue"] / prior[0]["revenue"]-1)*Decimal(100)
            period["growth_source"] = (prior[0]["start_date"], prior[0]["end_date"])
        result.append(period)
    return result


def compare_companies(data, tickers, mode, year, calendar_quarter=None, exact_end=None):
    result = []
    for company in data["companies"]:
        if company["ticker"] not in tickers:
            continue
        periods = [p for p in build_periods(data, company["cik"], mode) if p["end_date"].year == year
                   and (calendar_quarter is None or (p["end_date"].month-1)//3+1 == calendar_quarter)
                   and (exact_end is None or p["end_date"] == exact_end)]
        period = periods[0] if len(periods) == 1 else None
        result.append(dict(company=company, period=period,
                           reason="" if period else "No unique comparable reported period in this selection"))
    return result
